    c,w,a=p[0],p[1],p[2]
    e=np.exp(-a*t)
    return np.column_stack([x**1.5, x/(1+c*x)*v, t*np.log(t)*x**1.5, e*np.sin(w*t),e*np.cos(w*t)])
